package main

import (
	"encoding/json"
	"fmt"
	"os"
	"regexp"
	"strings"
)

type Config struct {
	Pipeline PipelineConfig `json:"pipeline"`
	Stages   []StageConfig  `json:"stages"`
}

type PipelineConfig struct {
	Name   string                 `json:"name"`
	Params map[string]interface{} `json:"params"`
}

type StageConfig struct {
	Name      string            `json:"name"`
	Type      string            `json:"type"`
	DependsOn []string          `json:"depends_on"`
	Inputs    map[string]string `json:"inputs"`
	Params    map[string]interface{} `json:"params"`
}

var paramRE = regexp.MustCompile(`\$\{([^}]+)\}`)

func loadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("file not found: %s", path)
		}
		return nil, err
	}
	var c Config
	if err := json.Unmarshal(data, &c); err != nil {
		return nil, fmt.Errorf("invalid config: %s", err.Error())
	}
	return &c, nil
}

func (c *Config) globalParams(overrides map[string]string) map[string]interface{} {
	params := map[string]interface{}{}
	for k, v := range c.Pipeline.Params {
		params[k] = v
	}
	for k, v := range overrides {
		params[k] = v
	}
	return params
}

func substituteValue(v interface{}, globals map[string]interface{}) interface{} {
	switch x := v.(type) {
	case string:
		return paramRE.ReplaceAllStringFunc(x, func(m string) string {
			key := m[2 : len(m)-1]
			if val, ok := globals[key]; ok {
				return fmt.Sprintf("%v", val)
			}
			return m
		})
	case map[string]interface{}:
		res := map[string]interface{}{}
		for k, val := range x {
			res[k] = substituteValue(val, globals)
		}
		return res
	case []interface{}:
		res := make([]interface{}, len(x))
		for i, val := range x {
			res[i] = substituteValue(val, globals)
		}
		return res
	default:
		return v
	}
}

func (c *Config) stageParams(name string, globals map[string]interface{}) map[string]interface{} {
	for _, s := range c.Stages {
		if s.Name == name {
			if s.Params == nil {
				return map[string]interface{}{}
			}
			res := substituteValue(s.Params, globals)
			if m, ok := res.(map[string]interface{}); ok {
				return m
			}
			return map[string]interface{}{}
		}
	}
	return map[string]interface{}{}
}

func (c *Config) stageByName(name string) (*StageConfig, bool) {
	for i := range c.Stages {
		if c.Stages[i].Name == name {
			return &c.Stages[i], true
		}
	}
	return nil, false
}

func validOutputPorts(t string) []string {
	switch t {
	case "data-source":
		return []string{"data"}
	case "transform":
		return []string{"data"}
	case "split":
		return []string{"train", "test"}
	case "train":
		return []string{"model", "predictions"}
	case "evaluate":
		return []string{"report"}
	case "register":
		return []string{"entry"}
	}
	return nil
}

func validStageType(t string) bool {
	switch t {
	case "data-source", "transform", "split", "train", "evaluate", "register":
		return true
	}
	return false
}

func (c *Config) Validate() (bool, []string) {
	errors := []string{}
	names := map[string]bool{}
	for i, s := range c.Stages {
		if s.Name == "" {
			errors = append(errors, fmt.Sprintf("stage at index %d has empty name", i))
			continue
		}
		if names[s.Name] {
			errors = append(errors, fmt.Sprintf("duplicate stage name: %s", s.Name))
		}
		names[s.Name] = true
		if !validStageType(s.Type) {
			errors = append(errors, fmt.Sprintf("stage %q has unknown type %q", s.Name, s.Type))
		}
		for _, dep := range s.DependsOn {
			if !names[dep] {
				errors = append(errors, fmt.Sprintf("stage %q references unknown dependency %q", s.Name, dep))
			}
		}
		for local, ref := range s.Inputs {
			parts := strings.SplitN(ref, ".", 2)
			if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
				errors = append(errors, fmt.Sprintf("stage %q input %q has invalid reference %q", s.Name, local, ref))
				continue
			}
			refStage, ok := c.stageByName(parts[0])
			if !ok {
				errors = append(errors, fmt.Sprintf("stage %q input %q references unknown stage %q", s.Name, local, parts[0]))
				continue
			}
			ports := validOutputPorts(refStage.Type)
			valid := false
			for _, p := range ports {
				if p == parts[1] {
					valid = true
					break
				}
			}
			if !valid {
				errors = append(errors, fmt.Sprintf("stage %q input %q references unknown output port %q on stage %q", s.Name, local, parts[1], parts[0]))
			}
		}
	}
	if cycle, stages := c.detectCycle(); cycle {
		errors = append(errors, fmt.Sprintf("cycle detected involving stages: %s", strings.Join(stages, ", ")))
	}
	return len(errors) == 0, errors
}

func (c *Config) detectCycle() ([]string, bool) {
	adj := map[string][]string{}
	for _, s := range c.Stages {
		adj[s.Name] = append(adj[s.Name], s.DependsOn...)
	}
	color := map[string]int{}
	var stack []string
	var cycle []string

	var dfs func(node string) bool
	dfs = func(node string) bool {
		if color[node] == 1 {
			idx := -1
			for i, n := range stack {
				if n == node {
					idx = i
					break
				}
			}
			if idx >= 0 {
				cycle = append([]string{}, stack[idx:]...)
				cycle = append(cycle, node)
				if len(cycle) > 1 && cycle[0] == cycle[len(cycle)-1] {
					cycle = cycle[:len(cycle)-1]
				}
			}
			return true
		}
		if color[node] == 2 {
			return false
		}
		color[node] = 1
		stack = append(stack, node)
		for _, dep := range adj[node] {
			if _, ok := adj[dep]; ok {
				if dfs(dep) {
					return true
				}
			}
		}
		stack = stack[:len(stack)-1]
		color[node] = 2
		return false
	}

	for _, s := range c.Stages {
		if color[s.Name] == 0 {
			if dfs(s.Name) {
				return cycle, true
			}
		}
	}
	return nil, false
}

func getString(params map[string]interface{}, key string) (string, bool) {
	v, ok := params[key]
	if !ok {
		return "", false
	}
	return fmt.Sprintf("%v", v), true
}

func getStringSlice(params map[string]interface{}, key string) ([]string, bool) {
	v, ok := params[key]
	if !ok {
		return nil, false
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, false
	}
	res := []string{}
	for _, item := range arr {
		res = append(res, fmt.Sprintf("%v", item))
	}
	return res, true
}

func getFloat(params map[string]interface{}, key string) (float64, bool) {
	v, ok := params[key]
	if !ok {
		return 0, false
	}
	switch x := v.(type) {
	case float64:
		return x, true
	case int:
		return float64(x), true
	case int64:
		return float64(x), true
	case string:
		return parseFloat64(x)
	}
	return 0, false
}

func getInt(params map[string]interface{}, key string) (int, bool) {
	v, ok := params[key]
	if !ok {
		return 0, false
	}
	switch x := v.(type) {
	case float64:
		return int(x), true
	case int:
		return x, true
	case int64:
		return int(x), true
	case string:
		f, ok := parseFloat64(x)
		if !ok {
			return 0, false
		}
		return int(f), true
	}
	return 0, false
}

func getMap(params map[string]interface{}, key string) (map[string]interface{}, bool) {
	v, ok := params[key]
	if !ok {
		return nil, false
	}
	m, ok := v.(map[string]interface{})
	return m, ok
}

func getFloatDefault(params map[string]interface{}, key string, def float64) float64 {
	if v, ok := getFloat(params, key); ok {
		return v
	}
	return def
}

func getIntDefault(params map[string]interface{}, key string, def int) int {
	if v, ok := getInt(params, key); ok {
		return v
	}
	return def
}
