package main

import (
	"encoding/csv"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

type Dataset struct {
	Columns []string     `json:"columns"`
	Types   []string     `json:"types"`
	Rows    [][]string   `json:"rows"`
}

func loadDataset(path string, schema map[string]interface{}) (*Dataset, error) {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("file not found: %s", path)
		}
		return nil, err
	}
	defer f.Close()

	r := csv.NewReader(f)
	records, err := r.ReadAll()
	if err != nil {
		return nil, err
	}
	if len(records) == 0 {
		return &Dataset{Columns: []string{}, Types: []string{}, Rows: [][]string{}}, nil
	}

	header := records[0]
	rows := records[1:]
	columns := header
	types := make([]string, len(columns))
	for i, col := range columns {
		if schemaType, ok := schema[col]; ok {
			types[i] = fmt.Sprintf("%v", schemaType)
		} else {
			types[i] = inferColumnType(rows, i)
		}
	}
	return &Dataset{Columns: columns, Types: types, Rows: rows}, nil
}

func inferColumnType(rows [][]string, idx int) string {
	for _, row := range rows {
		if idx >= len(row) {
			continue
		}
		val := strings.TrimSpace(row[idx])
		if val == "" {
			continue
		}
		if _, ok := parseFloat64(val); !ok {
			return "categorical"
		}
	}
	return "numeric"
}

func parseFloat64(s string) (float64, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, false
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, false
	}
	return f, true
}

func formatFloat(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 1) {
		return "+Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func (ds *Dataset) ColumnIndex(name string) (int, bool) {
	for i, c := range ds.Columns {
		if c == name {
			return i, true
		}
	}
	return -1, false
}

func (ds *Dataset) Copy() *Dataset {
	cols := append([]string{}, ds.Columns...)
	types := append([]string{}, ds.Types...)
	rows := make([][]string, len(ds.Rows))
	for i, row := range ds.Rows {
		rows[i] = append([]string{}, row...)
	}
	return &Dataset{Columns: cols, Types: types, Rows: rows}
}

func (ds *Dataset) Summary() map[string]interface{} {
	return map[string]interface{}{
		"rows":          len(ds.Rows),
		"columns":       len(ds.Columns),
		"column_names":  ds.Columns,
		"column_types":  ds.Types,
	}
}

func (ds *Dataset) NumericColumn(name string) ([]float64, error) {
	idx, ok := ds.ColumnIndex(name)
	if !ok {
		return nil, fmt.Errorf("column not found: %s", name)
	}
	if idx < len(ds.Types) && ds.Types[idx] != "numeric" {
		return nil, fmt.Errorf("column is not numeric: %s", name)
	}
	vals := make([]float64, len(ds.Rows))
	for i, row := range ds.Rows {
		if idx >= len(row) {
			return nil, fmt.Errorf("row %d missing column %s", i, name)
		}
		f, ok := parseFloat64(row[idx])
		if !ok {
			return nil, fmt.Errorf("non-numeric value in column %s: %s", name, row[idx])
		}
		vals[i] = f
	}
	return vals, nil
}

func (ds *Dataset) ColumnValues(name string) ([]string, error) {
	idx, ok := ds.ColumnIndex(name)
	if !ok {
		return nil, fmt.Errorf("column not found: %s", name)
	}
	vals := make([]string, len(ds.Rows))
	for i, row := range ds.Rows {
		if idx >= len(row) {
			return nil, fmt.Errorf("row %d missing column %s", i, name)
		}
		vals[i] = row[idx]
	}
	return vals, nil
}

func (ds *Dataset) featureMatrix(features []string) ([][]float64, error) {
	cols := make([]int, len(features))
	for i, f := range features {
		idx, ok := ds.ColumnIndex(f)
		if !ok {
			return nil, fmt.Errorf("feature column not found: %s", f)
		}
		if idx < len(ds.Types) && ds.Types[idx] != "numeric" {
			return nil, fmt.Errorf("feature column is not numeric: %s", f)
		}
		cols[i] = idx
	}
	X := make([][]float64, len(ds.Rows))
	for i, row := range ds.Rows {
		X[i] = make([]float64, len(features))
		for j, idx := range cols {
			if idx >= len(row) {
				return nil, fmt.Errorf("row %d missing column %s", i, features[j])
			}
			f, ok := parseFloat64(row[idx])
			if !ok {
				return nil, fmt.Errorf("non-numeric value in feature column %s: %s", features[j], row[idx])
			}
			X[i][j] = f
		}
	}
	return X, nil
}

func (ds *Dataset) setColumnValues(name string, values []string, typ string) {
	idx, ok := ds.ColumnIndex(name)
	if !ok {
		ds.Columns = append(ds.Columns, name)
		ds.Types = append(ds.Types, typ)
		for i, row := range ds.Rows {
			if i < len(values) {
				ds.Rows[i] = append(row, values[i])
			} else {
				ds.Rows[i] = append(row, "")
			}
		}
		return
	}
	if idx < len(ds.Types) {
		ds.Types[idx] = typ
	}
	for i, row := range ds.Rows {
		if i < len(values) && idx < len(row) {
			row[idx] = values[i]
		} else if i < len(values) {
			for len(row) <= idx {
				row = append(row, "")
			}
			row[idx] = values[i]
			ds.Rows[i] = row
		}
	}
}
EOF

