                    valid = true
                    break
                }
            }
            if !valid {
                errors = append(errors, fmt.Sprintf("stage %q input %q references unknown output port %q on stage %q", s.Name, local, parts[1], parts[0]))
            }
        }
    }
    if cycle, stages := c.detectCycle(); cycle {
        errors = append(errors, fmt.Sprintf("cycle detected involving stages: %s", strings.Join(stages, ", ")))
    }
    return len(errors) == 0, errors
}

func (c *Config) detectCycle() ([]string, bool) {
    adj := map[string][]string{}
    for _, s := range c.Stages {
        adj[s.Name] = append(adj[s.Name], s.DependsOn...)
    }
    color := map[string]int{}
    var stack []string
    var cycle []string

    var dfs func(node string) bool
    dfs = func(node string) bool {
        if color[node] == 1 {
            idx := -1
            for i, n := range stack {
                if n == node {
                    idx = i
                    break
                }
            }
            if idx >= 0 {
                cycle = append([]string{}, stack[idx:]...)
                cycle = append(cycle, node)
                if len(cycle) > 1 && cycle[0] == cycle[len(cycle)-1] {
                    cycle = cycle[:len(cycle)-1]
                }
            }
            return true
        }
        if color[node] == 2 {
            return false
        }
        color[node] = 1
        stack = append(stack, node)
        for _, dep := range adj[node] {
            if _, ok := adj[dep]; ok {
                if dfs(dep) {
                    return true
                }
            }
        }
        stack = stack[:len(stack)-1]
        color[node] = 2
        return false
    }

    for _, s := range c.Stages {
        if color[s.Name] == 0 {
            if dfs(s.Name) {
                return cycle, true
            }
        }
    }
    return nil, false
}

func getString(params map[string]interface{}, key string) (string, bool) {
    v, ok := params[key]
    if !ok {
        return "", false
    }
    return fmt.Sprintf("%v", v), true
}

func getStringSlice(params map[string]interface{}, key string) ([]string, bool) {
    v, ok := params[key]
    if !ok {
        return nil, false
    }
    arr, ok := v.([]interface{})
    if !ok {
        return nil, false
    }
    res := []string{}
    for _, item := range arr {
        res = append(res, fmt.Sprintf("%v", item))
    }
    return res, true
}

func getFloat(params map[string]interface{}, key string) (float64, bool) {
    v, ok := params[key]
    if !ok {
        return 0, false
    }
    switch x := v.(type) {
    case float64:
        return x, true
    case int:
        return float64(x), true
    case int64:
        return float64(x), true
    case string:
        return parseFloat64(x)
    }
    return 0, false
}

func getInt(params map[string]interface{}, key string) (int, bool) {
    v, ok := params[key]
    if !ok {
        return 0, false
    }
    switch x := v.(type) {
    case float64:
        return int(x), true
    case int:
        return x, true
    case int64:
        return int(x), true
    case string:
        f, ok := parseFloat64(x)
        if !ok {
            return 0, false
        }
        return int(f), true
    }
    return 0, false
}

func getMap(params map[string]interface{}, key string) (map[string]interface{}, bool) {
    v, ok := params[key]
    if !ok {
        return nil, false
    }
    m, ok := v.(map[string]interface{})
    return m, ok
}

func getFloatDefault(params map[string]interface{}, key string, def float64) float64 {
    if v, ok := getFloat(params, key); ok {
        return v
    }
    return def
}

func getIntDefault(params map[string]interface{}, key string, def int) int {
    if v, ok := getInt(params, key); ok {
        return v
    }
    return def
}
