cat > transform.go <<'EOF'
package main

import (
    "fmt"
    "math"
    "sort"
    "strconv"
    "strings"
)

func executeTransform(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue) (map[string]*ArtifactValue, error) {
    if inputs["data"] == nil || inputs["data"].Dataset == nil {
        return nil, fmt.Errorf("transform stage %q requires input data", stage.Name)
    }
    ds := inputs["data"].Dataset.Copy()

    opsVal, ok := params["operations"]
    if !ok {
        return nil, fmt.Errorf("transform stage %q missing operations", stage.Name)
    }
    ops, ok := opsVal.([]interface{})
    if !ok {
        return nil, fmt.Errorf("transform stage %q operations must be an array", stage.Name)
    }

    for i, opVal := range ops {
        op, ok := opVal.(map[string]interface{})
        if !ok {
            return nil, fmt.Errorf("operation %d in stage %q must be an object", i, stage.Name)
        }
        name, ok := getString(op, "op")
        if !ok {
            return nil, fmt.Errorf("operation %d in stage %q missing op", i, stage.Name)
        }
        var err error
        switch name {
        case "zscore":
            err = opZScore(ds, op)
        case "minmax":
            err = opMinMax(ds, op)
        case "onehot":
            err = opOneHot(ds, op)
        case "label_encode":
            err = opLabelEncode(ds, op)
        case "log":
            err = opLog(ds, op)
        case "polynomial":
            err = opPolynomial(ds, op)
        case "window_agg":
            err = opWindowAgg(ds, op)
        default:
            err = fmt.Errorf("unknown operation %q in stage %q", name, stage.Name)
        }
        if err != nil {
            return nil, err
        }
    }

    return map[string]*ArtifactValue{"data": {Dataset: ds}}, nil
}

func opZScore(ds *Dataset, op map[string]interface{}) error {
    cols, ok := getStringSlice(op, "columns")
    if !ok {
        return fmt.Errorf("zscore requires columns")
    }
    for _, col := range cols {
        vals, err := ds.NumericColumn(col)
        if err != nil {
            return err
        }
        mean := 0.0
        for _, v := range vals {
            mean += v
        }
        mean /= float64(len(vals))
        sumSq := 0.0
        for _, v := range vals {
            d := v - mean
            sumSq += d * d
        }
        std := math.Sqrt(sumSq / float64(len(vals)))
        out := make([]string, len(vals))
        for i, v := range vals {
            if std == 0 {
                out[i] = "0"
            } else {
                out[i] = formatFloat((v - mean) / std)
            }
        }
        ds.setColumnValues(col, out, "numeric")
    }
    return nil
}

func opMinMax(ds *Dataset, op map[string]interface{}) error {
    cols, ok := getStringSlice(op, "columns")
    if !ok {
        return fmt.Errorf("minmax requires columns")
    }
    minVal := getFloatDefault(op, "min", 0)
    maxVal := getFloatDefault(op, "max", 1)
    if maxVal < minVal {
        return fmt.Errorf("minmax max must be >= min")
    }
    for _, col := range cols {
        vals, err := ds.NumericColumn(col)
        if err != nil {
            return err
        }
        minCol := math.Inf(1)
        maxCol := math.Inf(-1)
        for _, v := range vals {
            if v < minCol {
                minCol = v
            }
            if v > maxCol {
                maxCol = v
            }
        }
        out := make([]string, len(vals))
        for i, v := range vals {
            if maxCol == minCol {
                out[i] = formatFloat(minVal)
            } else {
                scaled := (v-minCol)/(maxCol-minCol)*(maxVal-minVal) + minVal
                out[i] = formatFloat(scaled)
            }
        }
        ds.setColumnValues(col, out, "numeric")
    }
    return nil
}

func opOneHot(ds *Dataset, op map[string]interface{}) error {
    cols, ok := getStringSlice(op, "columns")
    if !ok {
        return fmt.Errorf("onehot requires columns")
    }
    for _, col := range cols {
        idx, ok := ds.ColumnIndex(col)
        if !ok {
            return fmt.Errorf("column not found: %s", col)
        }
        values := make([]string, len(ds.Rows))
        for i, row := range ds.Rows {
            if idx < len(row) {
                values[i] = row[idx]
            }
        }
        unique := uniqueStrings(values)
        sort.Strings(unique)

        newCols := make([]string, 0, len(ds.Columns)-1+len(unique))
        newTypes := make([]string, 0, len(ds.Columns)-1+len(unique))
        newRows := make([][]string, len(ds.Rows))
        for i := range ds.Rows {
            newRows[i] = make([]string, 0, len(newCols))
        }

        for j, c := range ds.Columns {
            if j == idx {
                for _, u := range unique {
                    newCols = append(newCols, col+"_"+u)
                    newTypes = append(newTypes, "numeric")
                    for i, row := range ds.Rows {
                        val := ""
                        if idx < len(row) {
                            val = row[idx]
                        }
                        if val == u {
                            newRows[i] = append(newRows[i], "1")
                        } else {
                            newRows[i] = append(newRows[i], "0")
                        }
                    }
                }
            } else {
                newCols = append(newCols, c)
                newTypes = append(newTypes, ds.Types[j])
                for i, row := range ds.Rows {
                    v := ""
                    if j < len(row) {
                        v = row[j]
                    }
                    newRows[i] = append(newRows[i], v)
                }
            }
        }
        ds.Columns = newCols
        ds.Types = newTypes
        ds.Rows = newRows
    }
    return nil
}

func opLabelEncode(ds *Dataset, op map[string]interface{}) error {
    cols, ok := getStringSlice(op, "columns")
    if !ok {
        return fmt.Errorf("label_encode requires columns")
    }
    for _, col := range cols {
        vals, err := ds.ColumnValues(col)
        if err != nil {
            return err
        }
        unique := uniqueStrings(vals)
        sort.Strings(unique)
        mapping := map[string]int{}
        for i, u := range unique {
            mapping[u] = i
        }
        out := make([]string, len(vals))
        for i, v := range vals {
            out[i] = strconv.Itoa(mapping[v])
        }
        ds.setColumnValues(col, out, "numeric")
    }
    return nil
}

func opLog(ds *Dataset, op map[string]interface{}) error {
    cols, ok := getStringSlice(op, "columns")
    if !ok {
        return fmt.Errorf("log requires columns")
    }
    for _, col := range cols {
        vals, err := ds.NumericColumn(col)
        if err != nil {
            return err
        }
        out := make([]string, len(vals))
        for i, v := range vals {
            if v <= 0 {
                return fmt.Errorf("log requires positive values")
            }
            out[i] = formatFloat(math.Log(v))
        }
        ds.setColumnValues(col, out, "numeric")
    }
    return nil
}

func opPolynomial(ds *Dataset, op map[string]interface{}) error {
    cols, ok := getStringSlice(op, "columns")
    if !ok {
        return fmt.Errorf("polynomial requires columns")
    }
    degree, ok := getInt(op, "degree")
    if !ok || degree < 2 {
        return fmt.Errorf("polynomial degree must be >= 2")
    }
    for _, col := range cols {
        if _, ok := ds.ColumnIndex(col); !ok {
            return fmt.Errorf("column not found: %s", col)
        }
    }

    type term struct {
        counts map[string]int
        tuple  []string
    }
    var terms []term

    var generate func(start int, depth int, chosen []string)
    generate = func(start int, depth int, chosen []string) {
        if depth == 0 {
            counts := map[string]int{}
            tuple := append([]string{}, chosen...)
            sort.Strings(tuple)
            for _, c := range tuple {
                counts[c]++
            }
            terms = append(terms, term{counts: counts, tuple: tuple})
            return
        }
        for i := start; i < len(cols); i++ {
            generate(i, depth-1, append(chosen, cols[i]))
        }
    }

    for d := 2; d <= degree; d++ {
        generate(0, d, []string{})
    }
    sort.Slice(terms, func(i, j int) bool {
        a := terms[i].tuple
        b := terms[j].tuple
        for k := 0; k < len(a) && k < len(b); k++ {
            if a[k] != b[k] {
                return a[k] < b[k]
            }
        }
        return len(a) < len(b)
    })

    colVals := map[string][]float64{}
    for _, col := range cols {
        vals, err := ds.NumericColumn(col)
        if err != nil {
            return err
        }
        colVals[col] = vals
    }

    for _, t := range terms {
        name := termName(t.counts)
        out := make([]string, len(ds.Rows))
        for i := range ds.Rows {
            val := 1.0
            for c, n := range t.counts {
                val *= math.Pow(colVals[c][i], float64(n))
            }
            out[i] = formatFloat(val)
        }
        ds.Columns = append(ds.Columns, name)
        ds.Types = append(ds.Types, "numeric")
        for i, row := range ds.Rows {
            ds.Rows[i] = append(row, out[i])
        }
    }
    return nil
}

func termName(counts map[string]int) string {
    keys := make([]string, 0, len(counts))
    for k := range counts {
        keys = append(keys, k)
    }
    sort.Strings(keys)
    parts := []string{}
    for _, k := range keys {
        n := counts[k]
        if n == 1 {
            parts = append(parts, k)
        } else {
            parts = append(parts, k+"^"+strconv.Itoa(n))
        }
    }
    return strings.Join(parts, "*")
}

func opWindowAgg(ds *Dataset, op map[string]interface{}) error {
    col, ok := getString(op, "column")
    if !ok {
