func executeSplit(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue) (map[string]*ArtifactValue, error) {
    var ds *Dataset
    for _, in := range inputs {
        if in != nil && in.Dataset != nil {
