    ratio, ok := getFloat(params, "ratio")
    if !ok || ratio <= 0 || ratio >= 1 {
        return nil, fmt.Errorf("split stage %q requires ratio in (0,1)", stage.Name)
    }
    seed, ok := getInt(params, "seed")
    if !ok {
        seed = 0
    }
    stratify, _ := getString(params, "stratify")

    train := ds.Copy()
    train.Rows = nil
    test := ds.Copy()
    test.Rows = nil

    appendRow := func(dst *Dataset, src []string) {
        dst.Rows = append(dst.Rows, append([]string{}, src...))
    }

    if stratify == "" {
        perm := rand.New(rand.NewSource(int64(seed))).Perm(len(ds.Rows))
        trainCount := int(float64(len(ds.Rows)) * ratio)
        for i, idx := range perm {
            if i < trainCount {
                appendRow(train, ds.Rows[idx])
            } else {
                appendRow(test, ds.Rows[idx])
            }
        }
    } else {
        idx, ok := ds.ColumnIndex(stratify)
        if !ok {
            return nil, fmt.Errorf("stratify column not found: %s", stratify)
        }
        classes := map[string][]int{}
        for i, row := range ds.Rows {
            val := ""
            if idx < len(row) {
                val = row[idx]
            }
            classes[val] = append(classes[val], i)
        }
        classNames := make([]string, 0, len(classes))
        for c := range classes {
            classNames = append(classNames, c)
        }
        // deterministic class order
        sortStrings(classNames)
        rng := rand.New(rand.NewSource(int64(seed)))
        for _, c := range classNames {
            rows := classes[c]
            perm := rng.Perm(len(rows))
            trainCount := int(float64(len(rows)) * ratio)
            for i, p := range perm {
                srcIdx := rows[p]
                if i < trainCount {
                    appendRow(train, ds.Rows[srcIdx])
                } else {
                    appendRow(test, ds.Rows[srcIdx])
                }
            }
        }
    }

    return map[string]*ArtifactValue{"train": {Dataset: train}, "test": {Dataset: test}}, nil
}

func sortStrings(s []string) {
    for i := 1; i < len(s); i++ {
        for j := i; j > 0 && s[j-1] > s[j]; j-- {
            s[j-1], s[j] = s[j], s[j-1]
        }
    }
