func trainLinearRegression(X [][]float64, y []float64) ([]float64, error) {
    n := len(X)
    if n == 0 {
        return nil, fmt.Errorf("no training data")
    }
    m := len(X[0])
    // design matrix with bias
    A := make([][]float64, n)
    for i := range X {
        A[i] = append([]float64{1}, X[i]...)
    }
    // normal equation: w = (A^T A)^-1 A^T y
    AtA := make([][]float64, m+1)
    for i := range AtA {
        AtA[i] = make([]float64, m+1)
    }
    AtY := make([]float64, m+1)
    for i := 0; i < n; i++ {
        for a := 0; a <= m; a++ {
            AtY[a] += A[i][a] * y[i]
            for b := 0; b <= m; b++ {
                AtA[a][b] += A[i][a] * A[i][b]
            }
        }
    }
    inv, err := invertMatrix(AtA)
    if err != nil {
        return nil, err
    }
    w := make([]float64, m+1)
    for a := 0; a <= m; a++ {
        for b := 0; b <= m; b++ {
            w[a] += inv[a][b] * AtY[b]
        }
    }
    return w, nil
}

func invertMatrix(m [][]float64) ([][]float64, error) {
    n := len(m)
    a := make([][]float64, n)
    for i := range m {
        a[i] = append([]float64{}, m[i]...)
        a[i] = append(a[i], make([]float64, n)...)
        a[i][n+i] = 1
    }
    for i := 0; i < n; i++ {
        pivot := a[i][i]
        if math.Abs(pivot) < 1e-12 {
            // try pivot swap
            swap := -1
            for r := i + 1; r < n; r++ {
                if math.Abs(a[r][i]) > 1e-12 {
                    swap = r
                    break
                }
            }
            if swap == -1 {
                return nil, fmt.Errorf("matrix not invertible")
            }
            a[i], a[swap] = a[swap], a[i]
            pivot = a[i][i]
        }
        for j := 0; j < 2*n; j++ {
            a[i][j] /= pivot
        }
        for r := 0; r < n; r++ {
            if r == i {
                continue
            }
            factor := a[r][i]
            for j := 0; j < 2*n; j++ {
                a[r][j] -= factor * a[i][j]
            }
        }
    }
    inv := make([][]float64, n)
    for i := range inv {
        inv[i] = make([]float64, n)
        copy(inv[i], a[i][n:])
    }
    return inv, nil
}

func trainLogisticRegression(X [][]float64, y []float64, lr float64, epochs int) ([]float64, error) {
    n := len(X)
    if n == 0 {
        return nil, fmt.Errorf("no training data")
    }
    m := len(X[0])
    w := make([]float64, m+1)
    for e := 0; e < epochs; e++ {
        grad := make([]float64, m+1)
        for i := 0; i < n; i++ {
            z := w[0]
            for j := 0; j < m; j++ {
                z += w[j+1] * X[i][j]
            }
            p := 1 / (1 + math.Exp(-z))
            err := p - y[i]
            grad[0] += err
            for j := 0; j < m; j++ {
                grad[j+1] += err * X[i][j]
            }
        }
        for j := range w {
            w[j] -= lr * grad[j] / float64(n)
        }
    }
    return w, nil
}

func trainDecisionTree(X [][]float64, y []float64, features []string, classification bool, depth, maxDepth, minSplit int) *TreeNode {
    node := &TreeNode{}
    if len(y) == 0 {
        node.IsLeaf = true
        return node
    }
    mean := 0.0
    for _, v := range y {
        mean += v
    }
    mean /= float64(len(y))

    if depth >= maxDepth || len(y) < minSplit || len(features) == 0 {
        node.IsLeaf = true
        node.Prediction = mean
        if classification {
            node.Probability = mean
        }
        return node
    }

    bestGain := 0.0
    bestFeature := -1
    bestThreshold := 0.0
    bestLeftIdx := []int(nil)
    bestRightIdx := []int(nil)

    impurity := giniOrVariance(y, classification)
    for j := 0; j < len(features); j++ {
        values := make([]float64, len(X))
        for i := 0; i < len(X); i++ {
            values[i] = X[i][j]
        }
        sorted := uniqueFloats(values)
        sort.Float64s(sorted)
        for s := 0; s < len(sorted)-1; s++ {
            threshold := (sorted[s] + sorted[s+1]) / 2
            leftIdx := []int{}
            rightIdx := []int{}
            for i := 0; i < len(X); i++ {
                if X[i][j] <= threshold {
                    leftIdx = append(leftIdx, i)
                } else {
                    rightIdx = append(rightIdx, i)
                }
            }
            if len(leftIdx) == 0 || len(rightIdx) == 0 {
                continue
            }
            leftY := subsetY(y, leftIdx)
            rightY := subsetY(y, rightIdx)
            leftImp := giniOrVariance(leftY, classification)
            rightImp := giniOrVariance(rightY, classification)
            gain := impurity - (float64(len(leftY))*leftImp+float64(len(rightY))*rightImp)/float64(len(y))
            if gain > bestGain {
                bestGain = gain
                bestFeature = j
                bestThreshold = threshold
                bestLeftIdx = leftIdx
                bestRightIdx = rightIdx
            }
        }
    }

    if bestFeature == -1 || bestGain <= 0 {
        node.IsLeaf = true
        node.Prediction = mean
        if classification {
            node.Probability = mean
        }
        return node
    }

    node.Feature = bestFeature
    node.Threshold = bestThreshold
    leftX := subsetRows(X, bestLeftIdx)
    rightX := subsetRows(X, bestRightIdx)
    node.Left = trainDecisionTree(leftX, subsetY(y, bestLeftIdx), features, classification, depth+1, maxDepth, minSplit)
    node.Right = trainDecisionTree(rightX, subsetY(y, bestRightIdx), features, classification, depth+1, maxDepth, minSplit)
    return node
}

func giniOrVariance(y []float64, classification bool) float64 {
    if len(y) == 0 {
        return 0
    }
    if classification {
        counts := map[float64]int{}
        for _, v := range y {
            counts[v]++
        }
        g := 1.0
        for _, c := range counts {
            p := float64(c) / float64(len(y))
            g -= p * p
        }
        return g
    }
    mean := 0.0
    for _, v := range y {
        mean += v
    }
    mean /= float64(len(y))
    sum := 0.0
    for _, v := range y {
        d := v - mean
        sum += d * d
    }
    return sum / float64(len(y))
}

func trainRandomForest(X [][]float64, y []float64, features []string, classification bool, nEst, maxDepth int, maxFeatures string, stageName string) []*TreeNode {
    forest := []*TreeNode{}
    rng := rand.New(rand.NewSource(int64(nEst * 12345)))
    m := len(features)
    mf := m
    switch maxFeatures {
    case "sqrt":
        mf = int(math.Sqrt(float64(m)))
    case "log2":
        mf = int(math.Log2(float64(m)))
    case "all":
        mf = m
    }
    if mf < 1 {
        mf = 1
    }
    for i := 0; i < nEst; i++ {
        n := len(X)
        idx := make([]int, n)
        for j := 0; j < n; j++ {
            idx[j] = rng.Intn(n)
        }
        bootX := subsetRows(X, idx)
        bootY := subsetY(y, idx)
        // feature subset: use all features but limit split search by selecting features
        selected := rng.Perm(m)
        selected = selected[:mf]
        subFeatures := []string{}
        subX := make([][]float64, len(bootX))
        for r := range bootX {
            subX[r] = []float64{}
            for _, s := range selected {
                subX[r] = append(subX[r], bootX[r][s])
            }
        }
        for _, s := range selected {
            subFeatures = append(subFeatures, features[s])
        }
        tree := trainDecisionTree(subX, bootY, subFeatures, classification, 0, maxDepth, 2)
        forest = append(forest, tree)
    }
    return forest
}

func trainGradientBoost(X [][]float64, y []float64, classification bool, nEst int, lr float64, maxDepth int) []*BoostedTree {
    trees := []*BoostedTree{}
    init := 0.0
    if classification {
        p := 0.0
        for _, v := range y {
            p += v
        }
        p /= float64(len(y))
        if p <= 0 {
            p = 1e-15
        }
        if p >= 1 {
            p = 1 - 1e-15
        }
        init = math.Log(p / (1 - p))
    } else {
        for _, v := range y {
            init += v
        }
        init /= float64(len(y))
    }

    current := make([]float64, len(y))
    for i := range y {
        current[i] = init
    }
    features := []string{}
    for j := 0; j < len(X[0]); j++ {
        features = append(features, fmt.Sprintf("f%d", j))
    }

    for i := 0; i < nEst; i++ {
        residual := make([]float64, len(y))
        if classification {
            for j := range y {
                p := 1 / (1 + math.Exp(-current[j]))
                residual[j] = y[j] - p
            }
        } else {
            for j := range y {
                residual[j] = y[j] - current[j]
            }
        }
        tree := trainDecisionTree(X, residual, features, false, 0, maxDepth, 2)
        trees = append(trees, &BoostedTree{Tree: tree, LearningRate: lr, InitPrediction: init})
        for j := range y {
            current[j] += lr * predictTree(tree, X[j])
        }
    }
    return trees
}

func (m *Model) PredictBatch(X [][]float64) []float64 {
    preds := make([]float64, len(X))
    for i := range X {
        preds[i] = m.Predict(X[i])
    }
    return preds
}

func (m *Model) Predict(x []float64) float64 {
    switch m.Algorithm {
    case "linear-regression":
        z := m.LinearWeights[0]
        for j := 0; j < len(x); j++ {
            z += m.LinearWeights[j+1] * x[j]
        }
        return z
    case "logistic-regression":
        z := m.LogisticWeights[0]
        for j := 0; j < len(x); j++ {
            z += m.LogisticWeights[j+1] * x[j]
        }
        return 1 / (1 + math.Exp(-z))
    case "decision-tree":
        if m.Classification {
            return predictTreeProb(m.Tree, x)
        }
        return predictTree(m.Tree, x)
    case "random-forest":
        if m.Classification {
            sum := 0.0
            for _, t := range m.Forest {
                sum += predictTreeProb(t, x)
            }
            return sum / float64(len(m.Forest))
        }
        sum := 0.0
        for _, t := range m.Forest {
            sum += predictTree(t, x)
        }
        return sum / float64(len(m.Forest))
    case "gradient-boost":
        if len(m.Boost) == 0 {
            return 0
        }
        current := m.Boost[0].InitPrediction
        for _, b := range m.Boost {
            current += b.LearningRate * predictTree(b.Tree, x)
        }
        if m.Classification {
            return 1 / (1 + math.Exp(-current))
        }
        return current
    case "knn":
        return predictKNN(m.KNN, x)
    }
    return 0
}

func predictTree(node *TreeNode, x []float64) float64 {
    if node == nil || node.IsLeaf {
        if node == nil {
            return 0
        }
        return node.Prediction
    }
    if node.Feature < len(x) && x[node.Feature] <= node.Threshold {
        return predictTree(node.Left, x)
    }
    return predictTree(node.Right, x)
}

func predictTreeProb(node *TreeNode, x []float64) float64 {
    if node == nil || node.IsLeaf {
        if node == nil {
            return 0
        }
        return node.Probability
    }
    if node.Feature < len(x) && x[node.Feature] <= node.Threshold {
        return predictTreeProb(node.Left, x)
    }
    return predictTreeProb(node.Right, x)
}

func predictKNN(knn *KNNModel, x []float64) float64 {
    if knn == nil || len(knn.Features) == 0 {
        return 0
    }
    type pair struct {
        dist float64
        target float64
    }
    pairs := make([]pair, len(knn.Features))
    for i := range knn.Features {
        d := 0.0
        for j := range x {
            diff := x[j] - knn.Features[i][j]
            d += diff * diff
        }
        pairs[i] = pair{dist: d, target: knn.Targets[i]}
    }
    sort.Slice(pairs, func(i, j int) bool {
        return pairs[i].dist < pairs[j].dist
    })
    k := knn.K
    if k > len(pairs) {
        k = len(pairs)
    }
    if knn.Classification {
        votes := map[float64]int{}
        for i := 0; i < k; i++ {
            votes[pairs[i].target]++
        }
        bestCount := -1
        bestVal := 0.0
        for val, c := range votes {
            if c > bestCount || (c == bestCount && val < bestVal) {
                bestCount = c
                bestVal = val
            }
        }
        // probability of positive class
        pos := 0
        for i := 0; i < k; i++ {
            if pairs[i].target == 1 {
                pos++
            }
        }
        return float64(pos) / float64(k)
    }
    sum := 0.0
    for i := 0; i < k; i++ {
        sum += pairs[i].target
    }
    return sum / float64(k)
}

func subsetRows(X [][]float64, idx []int) [][]float64 {
    res := make([][]float64, len(idx))
    for i, j := range idx {
        res[i] = append([]float64{}, X[j]...)
    }
    return res
}

func subsetY(y []float64, idx []int) []float64 {
    res := make([]float64, len(idx))
    for i, j := range idx {
        res[i] = y[j]
    }
    return res
}

func uniqueFloats(vals []float64) []float64 {
    seen := map[float64]bool{}
    res := []float64{}
    for _, v := range vals {
        if !seen[v] {
            seen[v] = true
            res = append(res, v)
        }
    }
    return res
}
