package main

import (
    "fmt"
    "math"
    "sort"
)

type Report struct {
    Metrics map[string]interface{} `json:"metrics"`
    Pass    bool                   `json:"pass"`
}

func executeEvaluate(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue) (map[string]*ArtifactValue, error) {
    modelVal := inputs["model"]
    if modelVal == nil || modelVal.Model == nil {
        return nil, fmt.Errorf("evaluate stage %q requires model input", stage.Name)
    }
    ds := inputDataset(inputs)
    if ds == nil {
        return nil, fmt.Errorf("evaluate stage %q requires data input", stage.Name)
    }
    model := modelVal.Model

    metrics, ok := getStringSlice(params, "metrics")
    if !ok {
        return nil, fmt.Errorf("evaluate stage %q requires metrics", stage.Name)
    }
    threshold, _ := getMap(params, "threshold")

    y, err := ds.NumericColumn(model.Target)
    if err != nil {
        return nil, err
    }
    X, err := ds.featureMatrix(model.Features)
    if err != nil {
        return nil, err
    }
    preds := model.PredictBatch(X)
    classification := isBinary01(y)

    report := &Report{Metrics: map[string]interface{}{}, Pass: true}

    for _, metric := range metrics {
        var val interface{}
        var err error
        switch metric {
        case "accuracy", "precision", "recall", "f1", "auc", "logloss", "confusion_matrix":
            if !classification {
                err = fmt.Errorf("metric %q requires binary 0/1 target", metric)
            } else {
                val, err = classificationMetric(metric, y, preds)
            }
        case "mse", "rmse", "mae", "r2", "mape":
            if classification {
                err = fmt.Errorf("metric %q requires regression target", metric)
            } else {
                val, err = regressionMetric(metric, y, preds)
            }
        default:
            err = fmt.Errorf("unknown metric %q", metric)
        }
        if err != nil {
            return nil, err
        }
        report.Metrics[metric] = val
    }

    if threshold != nil {
        for metricName, thresholdVal := range threshold {
            metricValue, ok := report.Metrics[metricName]
            if !ok {
                continue
            }
            fv, ok := toFloat64(metricValue)
            if !ok {
                continue
            }
            tv, ok := toFloat64(thresholdVal)
            if !ok {
                continue
            }
            if fv < tv {
                report.Pass = false
            }
        }
    }

    return map[string]*ArtifactValue{"report": {Report: report}}, nil
}

func classificationMetric(name string, y []float64, preds []float64) (interface{}, error) {
    labels := make([]int, len(preds))
    for i, p := range preds {
        if p >= 0.5 {
            labels[i] = 1
        } else {
            labels[i] = 0
        }
    }
    switch name {
    case "accuracy":
        correct := 0
        for i := range y {
            if labels[i] == int(y[i]) {
                correct++
            }
        }
        return float64(correct) / float64(len(y)), nil
    case "precision":
        tp, fp := 0, 0
        for i := range y {
            if labels[i] == 1 {
                if y[i] == 1 {
                    tp++
                } else {
                    fp++
                }
            }
        }
        if tp+fp == 0 {
            return 0.0, nil
        }
        return float64(tp) / float64(tp+fp), nil
    case "recall":
        tp, fn := 0, 0
        for i := range y {
            if y[i] == 1 {
                if labels[i] == 1 {
                    tp++
                } else {
                    fn++
                }
            }
        }
        if tp+fn == 0 {
            return 0.0, nil
        }
        return float64(tp) / float64(tp+fn), nil
    case "f1":
        p, _ := classificationMetric("precision", y, preds)
        r, _ := classificationMetric("recall", y, preds)
        pf := p.(float64)
        rf := r.(float64)
        if pf+rf == 0 {
            return 0.0, nil
        }
        return 2 * pf * rf / (pf + rf), nil
    case "auc":
        return aucROC(y, preds), nil
    case "logloss":
        sum := 0.0
        for i := range y {
            p := clamp(preds[i], 1e-15, 1-1e-15)
            sum += y[i]*math.Log(p) + (1-y[i])*math.Log(1-p)
        }
        return -sum / float64(len(y)), nil
    case "confusion_matrix":
        tp, fp, tn, fn := 0, 0, 0, 0
        for i := range y {
            if labels[i] == 1 && y[i] == 1 {
                tp++
            } else if labels[i] == 1 && y[i] == 0 {
                fp++
            } else if labels[i] == 0 && y[i] == 0 {
                tn++
            } else {
                fn++
            }
        }
        return map[string]int{"tp": tp, "fp": fp, "tn": tn, "fn": fn}, nil
    }
    return nil, fmt.Errorf("unknown classification metric %q", name)
}

func regressionMetric(name string, y []float64, preds []float64) (interface{}, error) {
    n := float64(len(y))
    switch name {
    case "mse":
        sum := 0.0
        for i := range y {
            d := y[i] - preds[i]
            sum += d * d
        }
        return sum / n, nil
    case "rmse":
        mse, _ := regressionMetric("mse", y, preds)
        return math.Sqrt(mse.(float64)), nil
    case "mae":
        sum := 0.0
        for i := range y {
            sum += math.Abs(y[i] - preds[i])
        }
        return sum / n, nil
    case "r2":
        mean := 0.0
        for _, v := range y {
            mean += v
        }
        mean /= n
        ssRes := 0.0
        ssTot := 0.0
        for i := range y {
            ssRes += (y[i] - preds[i]) * (y[i] - preds[i])
            ssTot += (y[i] - mean) * (y[i] - mean)
        }
        if ssTot == 0 {
            return 0.0, nil
        }
        return 1 - ssRes/ssTot, nil
    case "mape":
        sum := 0.0
        count := 0.0
        for i := range y {
            if y[i] == 0 {
                continue
            }
            sum += math.Abs((y[i] - preds[i]) / y[i])
            count++
        }
        if count == 0 {
            return 0.0, nil
        }
        return sum / count * 100, nil
    }
    return nil, fmt.Errorf("unknown regression metric %q", name)
}

func aucROC(y []float64, scores []float64) float64 {
    type point struct {
        score float64
        y     float64
    }
    pts := make([]point, len(y))
    pos := 0
    neg := 0
    for i := range y {
        pts[i] = point{scores[i], y[i]}
        if y[i] == 1 {
            pos++
        } else {
            neg++
        }
    }
    if pos == 0 || neg == 0 {
        return 0.0
    }
    sort.Slice(pts, func(i, j int) bool {
        if pts[i].score != pts[j].score {
            return pts[i].score > pts[j].score
        }
        return pts[i].y > pts[j].y
    })

    area := 0.0
    tp := 0.0
    fp := 0.0
    prevTP := 0.0
    prevFP := 0.0
    i := 0
    for i < len(pts) {
        j := i
        for j < len(pts) && pts[j].score == pts[i].score {
            j++
        }
        for k := i; k < j; k++ {
            if pts[k].y == 1 {
                tp++
            } else {
                fp++
            }
        }
        area += (fp - prevFP) * (tp + prevTP) / 2.0
        prevTP = tp
        prevFP = fp
        i = j
    }
    return area / (float64(pos) * float64(neg))
}

func clamp(v, lo, hi float64) float64 {
    if v < lo {
        return lo
    }
    if v > hi {
        return hi
    }
    return v
}

func toFloat64(v interface{}) (float64, bool) {
    switch x := v.(type) {
    case float64:
        return x, true
    case int:
        return float64(x), true
    case int64:
        return float64(x), true
    }
    return 0, false
}

func (r *Report) Summary() map[string]interface{} {
    return map[string]interface{}{
        "metrics": r.Metrics,
        "pass":    r.Pass,
    }
}
