package main

import (
    "encoding/json"
    "fmt"
    "os"
    "path/filepath"
    "sort"
    "time"
)

type RegistryEntry struct {
    Name           string                 `json:"name"`
    Version        int                    `json:"version"`
    Stage          string                 `json:"stage"`
    Tags           []string               `json:"tags"`
    Metrics        map[string]interface{} `json:"metrics"`
    Hyperparams    map[string]interface{} `json:"hyperparams"`
    ArtifactRefs   map[string]string      `json:"artifact_refs"`
    PromotionRules map[string]interface{} `json:"promotion_rules"`
    RegisteredAt   string                 `json:"registered_at"`
}

func executeRegister(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue) (map[string]*ArtifactValue, error) {
    modelVal := inputs["model"]
    if modelVal == nil || modelVal.Model == nil {
        return nil, fmt.Errorf("register stage %q requires model input", stage.Name)
    }
    reportVal := inputs["report"]
    if reportVal == nil || reportVal.Report == nil {
        return nil, fmt.Errorf("register stage %q requires report input", stage.Name)
    }

    name, ok := getString(params, "model_name")
    if !ok {
        return nil, fmt.Errorf("register stage %q requires model_name", stage.Name)
    }
    tags, _ := getStringSlice(params, "tags")
    if tags == nil {
        tags = []string{}
    }
    stageName, _ := getString(params, "stage")
    if stageName == "" {
        stageName = "staging"
    }
    if stageName != "staging" && stageName != "production" {
        return nil, fmt.Errorf("register stage %q invalid stage %q", stage.Name, stageName)
    }
    rules, _ := getMap(params, "promotion_rules")

    registry, err := loadRegistry()
    if err != nil {
        return nil, err
    }
    version := 1
    for _, e := range registry {
        if e.Name == name && e.Version >= version {
            version = e.Version + 1
        }
    }

    entry := &RegistryEntry{
        Name:           name,
        Version:        version,
        Stage:          stageName,
        Tags:           tags,
        Metrics:        reportVal.Report.Metrics,
        Hyperparams:    modelVal.Model.Hyperparams,
        ArtifactRefs:   map[string]string{},
        PromotionRules: rules,
        RegisteredAt:   time.Now().UTC().Format(time.RFC3339),
    }
    registry = append(registry, entry)
    if err := saveRegistry(registry); err != nil {
        return nil, err
    }

    return map[string]*ArtifactValue{"entry": {Entry: entry}}, nil
}

func registryPath() string {
    return filepath.Join(".mlpipe", "registry.json")
}

func loadRegistry() ([]*RegistryEntry, error) {
    data, err := os.ReadFile(registryPath())
    if err != nil {
        if os.IsNotExist(err) {
            return []*RegistryEntry{}, nil
        }
        return nil, err
    }
    var entries []*RegistryEntry
    if err := json.Unmarshal(data, &entries); err != nil {
        return nil, err
    }
    return entries, nil
}

func saveRegistry(entries []*RegistryEntry) error {
    if err := os.MkdirAll(".mlpipe", 0755); err != nil {
        return err
    }
    data, err := json.MarshalIndent(entries, "", "  ")
    if err != nil {
        return err
    }
    return os.WriteFile(registryPath(), data, 0644)
}

func listRegistry(name, stage, tag string) ([]*RegistryEntry, error) {
    entries, err := loadRegistry()
    if err != nil {
        return nil, err
    }
    filtered := []*RegistryEntry{}
    for _, e := range entries {
        if name != "" && e.Name != name {
            continue
        }
        if stage != "" && e.Stage != stage {
            continue
        }
        if tag != "" {
            found := false
            for _, t := range e.Tags {
                if t == tag {
                    found = true
                    break
                }
            }
            if !found {
                continue
            }
        }
        filtered = append(filtered, e)
    }
    sort.Slice(filtered, func(i, j int) bool {
        if filtered[i].Name != filtered[j].Name {
            return filtered[i].Name < filtered[j].Name
        }
        return filtered[i].Version > filtered[j].Version
    })
    return filtered, nil
}

func registryInfo(name string, version int) (*RegistryEntry, error) {
    entries, err := loadRegistry()
    if err != nil {
        return nil, err
    }
    for _, e := range entries {
        if e.Name == name && e.Version == version {
            return e, nil
        }
    }
    return nil, fmt.Errorf("model not found: %s:%d", name, version)
}

func promoteModel(name string, version int, targetStage string) (*RegistryEntry, string, string, error) {
    valid := map[string]bool{"staging": true, "production": true, "archived": true}
    if !valid[targetStage] {
        return nil, "", "", fmt.Errorf("invalid promotion: invalid target stage %q", targetStage)
    }
    entries, err := loadRegistry()
    if err != nil {
        return nil, "", "", err
    }
    var entry *RegistryEntry
    for _, e := range entries {
        if e.Name == name && e.Version == version {
            entry = e
            break
        }
    }
    if entry == nil {
        return nil, "", "", fmt.Errorf("model not found: %s:%d", name, version)
    }

    prevStage := entry.Stage
    if !validPromotionTransition(prevStage, targetStage) {
        return nil, "", "", fmt.Errorf("invalid promotion: cannot promote from %s to %s", prevStage, targetStage)
    }

    if targetStage == "production" {
        if entry.PromotionRules != nil {
            if rules, ok := entry.PromotionRules[targetStage].(map[string]interface{}); ok {
                for metricName, thresholdVal := range rules {
                    metricValue, ok := entry.Metrics[metricName]
                    if !ok {
                        continue
                    }
                    mv, ok := toFloat64(metricValue)
                    if !ok {
                        continue
                    }
                    tv, ok := toFloat64(thresholdVal)
                    if !ok {
                        continue
                    }
                    if mv < tv {
                        return nil, prevStage, targetStage, fmt.Errorf("metric %s (%v) below threshold (%v)", metricName, mv, tv)
                    }
                }
            }
        }
        for _, e := range entries {
            if e.Name == name && e.Stage == "production" && e.Version != version {
                e.Stage = "archived"
            }
        }
    }

    entry.Stage = targetStage
    if err := saveRegistry(entries); err != nil {
        return nil, "", "", err
    }
    return entry, prevStage, targetStage, nil
}

func validPromotionTransition(from, to string) bool {
    if from == "staging" && to == "production" {
        return true
    }
    if from == "production" && to == "archived" {
        return true
    }
    return false
}

