        }
        metricsDiff[k] = map[string]interface{}{"v1": mv1, "v2": mv2, "delta": delta, "pct_change": pct}
    }

    hpDiff := map[string]interface{}{}
    hpNames := map[string]bool{}
    for k := range e1.Hyperparams {
        hpNames[k] = true
