package main

import (
    "encoding/json"
    "fmt"
    "os"
    "strings"
)

func main() {
    if len(os.Args) < 2 {
        printError("usage: mlpipe <command> [args]")
        return
    }

    cmd := os.Args[1]
    args := os.Args[2:]

    switch cmd {
    case "run":
        cmdRun(args)
    case "validate":
        cmdValidate(args)
    case "registry":
        cmdRegistry(args)
    case "lineage":
        cmdLineage(args)
    default:
        printError(fmt.Sprintf("unknown command: %s", cmd))
    }
}

func cmdRun(args []string) {
    if len(args) < 1 {
        printError("usage: mlpipe run <config.json> [--param key=value ...]")
        return
    }
    configPath := args[0]
    overrides, err := parseParams(args[1:])
    if err != nil {
        printError(err.Error())
        return
    }
    config, err := loadConfig(configPath)
    if err != nil {
        printError(err.Error())
        return
    }
    executor := NewExecutor(config, overrides)
    run, err := executor.Run()
    if err != nil {
        printError(err.Error())
        return
    }
    printJSON(run)
}

func cmdValidate(args []string) {
    if len(args) < 1 {
        printError("usage: mlpipe validate <config.json>")
        return
    }
    config, err := loadConfig(args[0])
    if err != nil {
        printError(err.Error())
        return
    }
    valid, errors := config.Validate()
    printJSON(map[string]interface{}{"valid": valid, "errors": errors})
}

func cmdRegistry(args []string) {
    if len(args) < 1 {
        printError("usage: mlpipe registry <list|info|promote|compare> [args]")
