    for i := 0; i < len(args); i++ {
        switch {
        case args[i] == "--name" && i+1 < len(args):
            name = args[i+1]
            i++
        case strings.HasPrefix(args[i], "--name="):
            name = strings.TrimPrefix(args[i], "--name=")
