            i++
        case strings.HasPrefix(args[i], "--stage="):
            stage = strings.TrimPrefix(args[i], "--stage=")
        case args[i] == "--tag" && i+1 < len(args):
            tag = args[i+1]
            i++
        case strings.HasPrefix(args[i], "--tag="):
            tag = strings.TrimPrefix(args[i], "--tag=")
        default:
            printError(fmt.Sprintf("unknown flag: %s", args[i]))
            return
        }
    }
    entries, err := listRegistry(name, stage, tag)
    if err != nil {
