}

func cmdRegistryInfo(args []string) {
    if len(args) < 1 {
        printError("usage: mlpipe registry info <name>:<version>")
        return
    }
    name, version, ok := splitNameVersion(args[0])
    if !ok {
        printError("invalid name:version format")
        return
    }
    entry, err := registryInfo(name, version)
    if err != nil {
        printError(err.Error())
        return
    }
    printJSON(entry)
}

func cmdRegistryPromote(args []string) {
    if len(args) < 2 {
        printError("usage: mlpipe registry promote <name>:<version> <target_stage>")
        return
    }
    name, version, ok := splitNameVersion(args[0])
    if !ok {
        printError("invalid name:version format")
        return
    }
    target := args[1]
    entry, prev, new, err := promoteModel(name, version, target)
    if err != nil {
        if strings.HasPrefix(err.Error(), "metric ") {
            printJSON(map[string]interface{}{"success": false, "message": err.Error()})
            return
        }
        printError(err.Error())
        return
    }
    printJSON(map[string]interface{}{
        "success":       true,
        "message":       fmt.Sprintf("promoted to %s", new),
        "previous_stage": prev,
        "new_stage":      entry.Stage,
    })
}

func cmdRegistryCompare(args []string) {
    if len(args) < 2 {
        printError("usage: mlpipe registry compare <name>:<v1> <name>:<v2>")
        return
    }
    name1, v1, ok := splitNameVersion(args[0])
    if !ok {
        printError("invalid name:version format")
        return
    }
    name2, v2, ok := splitNameVersion(args[1])
    if !ok {
        printError("invalid name:version format")
        return
    }
    if name1 != name2 {
        printError("model names must match")
        return
    }
    result, err := compareModels(name1, v1, v2)
    if err != nil {
        printError(err.Error())
        return
    }
    printJSON(result)
}

func cmdLineage(args []string) {
    if len(args) < 1 {
        printError("usage: mlpipe lineage <artifact_id> [--direction up|down|both]")
        return
    }
    id := args[0]
    direction := "both"
    for i := 1; i < len(args); i++ {
        if args[i] == "--direction" && i+1 < len(args) {
            direction = args[i+1]
            i++
        } else if strings.HasPrefix(args[i], "--direction=") {
            direction = strings.TrimPrefix(args[i], "--direction=")
        } else {
            printError(fmt.Sprintf("unknown flag: %s", args[i]))
            return
        }
    }
    result, err := queryLineage(id, direction)
    if err != nil {
        printError(err.Error())
        return
    }
    printJSON(result)
