func parseParams(args []string) (map[string]string, error) {
    overrides := map[string]string{}
    for i := 0; i < len(args); i++ {
        if args[i] == "--param" {
            if i+1 >= len(args) {
                return nil, fmt.Errorf("--param requires key=value")
            }
            kv := args[i+1]
            i++
            k, v, ok := strings.Cut(kv, "=")
            if !ok {
                return nil, fmt.Errorf("--param requires key=value")
            }
            overrides[k] = v
        } else if strings.HasPrefix(args[i], "--param=") {
            kv := strings.TrimPrefix(args[i], "--param=")
            k, v, ok := strings.Cut(kv, "=")
            if !ok {
                return nil, fmt.Errorf("--param requires key=value")
            }
            overrides[k] = v
        } else {
            return nil, fmt.Errorf("unknown flag: %s", args[i])
        }
    }
    return overrides, nil
}

func splitNameVersion(s string) (string, int, bool) {
    parts := strings.SplitN(s, ":", 2)
    if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
        return "", 0, false
    }
    var version int
    if _, err := fmt.Sscanf(parts[1], "%d", &version); err != nil {
        return "", 0, false
    }
    return parts[0], version, true
}

func printJSON(v interface{}) {
    data, err := json.MarshalIndent(v, "", "  ")
    if err != nil {
        printError(err.Error())
        return
    }
    fmt.Println(string(data))
}

func printError(msg string) {
    data, _ := json.Marshal(map[string]string{"error": msg})
    fmt.Fprintln(os.Stderr, string(data))
    os.Exit(1)
}
