func trainDecisionTreeFeatures(X [][]float64, y []float64, features []string, featureIdx []int, classification bool, depth, maxDepth, minSplit int) *TreeNode {
    node := &TreeNode{}
    if len(y) == 0 {
        node.IsLeaf = true
        return node
    }
    mean := 0.0
    for _, v := range y {
        mean += v
    }
    mean /= float64(len(y))

    if depth >= maxDepth || len(y) < minSplit || len(featureIdx) == 0 {
        node.IsLeaf = true
        node.Prediction = mean
        if classification {
            node.Probability = mean
        }
        return node
    }

    bestGain := 0.0
    bestFeaturePos := -1
    bestFeatureIdx := -1
    bestThreshold := 0.0
    bestLeftIdx := []int(nil)
    bestRightIdx := []int(nil)

    impurity := giniOrVariance(y, classification)
    for pos, j := range featureIdx {
        values := make([]float64, len(X))
        for i := 0; i < len(X); i++ {
            values[i] = X[i][j]
        }
        sorted := uniqueFloats(values)
